import { Transport } from "./lab4.js";
var DocType = Transport.DocType;
var Vehicle = Transport.Vehicle;
var VehicleOwner = Transport.VehicleOwner;
var Motorbike = Transport.Motorbike;
var VehicleStorageImpl = Transport.VehicleStorageImpl;
const owner = new VehicleOwner("Quoc", "Tran", "Van", new Date(2002, 4, 19), DocType.passport, "123456", "567890");
const bike = new Motorbike("Yamaha", "YZF-R1", 2023, "1YVHZ8CBX5M123456", "B456CD", owner, "Спортивная", true);
console.log("-------------------------------");
bike.displayVehicle();
const vehicleStorage = new VehicleStorageImpl();
const car_toyota = new Vehicle("Toyota", "Camry", 2022, "1HGCM82633A123456", "A123BC", owner);
const car_honda = new Vehicle("Honda", "Civic", 2023, "1HGCM82633A654321", "B456CD", owner);
vehicleStorage.addVehicle(car_toyota);
vehicleStorage.addVehicle(car_honda);
const allVehicles = vehicleStorage.getAllVehicles();
console.log("-------------------------------");
console.log("Все автомобили в хранилище:");
allVehicles.forEach(vehicle => vehicle.displayVehicle());
